/* ============================================================
   PATCH 1.0.15 — страж task_id при сохранении задачи
   Если modal открыт как «Редактировать», но #task_id пуст
   (например, _restructure удалил его до применения 1.0.14)
   — восстанавливаем id по имени из state.tasks, иначе отменяем
   сохранение (лучше отказ, чем дубликат).
   ============================================================ */
(function(){
'use strict';
if (window.__trkTaskIdGuardV1015) return;
window.__trkTaskIdGuardV1015 = true;

var _guardTaskId = '';
var _guardOpenTask = null;

function _notify(msg, kind){
    if (typeof window.__trackerNotify === 'function') {
        try { window.__trackerNotify(msg, kind); return; } catch(e){}
    }
    console.warn('[task_id-guard]', msg);
}

function _ensureHiddenInModal(){
    var tm = document.getElementById('taskModal');
    if (!tm) return null;
    var content = tm.querySelector('.modal-content');
    if (!content) return null;
    var el = document.getElementById('task_id');
    if (!el) {
        el = document.createElement('input');
        el.type = 'hidden';
        el.id = 'task_id';
        el.value = '';
        content.insertBefore(el, content.firstChild);
    }
    return el;
}

function _isEditMode(){
    var t = document.getElementById('taskModalTitle');
    if (!t) return false;
    var txt = t.textContent || '';
    return txt.indexOf('Редакт') !== -1;
}

function _findTaskIdByName(name){
    if (!name) return '';
    var st = window.__trkState || {};
    var tasks = st.tasks || [];
    for (var i = 0; i < tasks.length; i++) {
        if (tasks[i] && tasks[i].name === name) return tasks[i].id || '';
    }
    return '';
}

// 1. Обёртка window.__trkOpenTaskModal: запоминаем id при каждом открытии
function _wrapOpen(){
    var curr = window.__trkOpenTaskModal;
    if (typeof curr !== 'function' || curr._taskIdGuard) return;
    var wrapped = function(task){
        _guardTaskId = (task && task.id) ? String(task.id) : '';
        _guardOpenTask = task || null;
        var el = _ensureHiddenInModal();
        if (el) el.value = _guardTaskId;
        return curr.apply(this, arguments);
    };
    wrapped._taskIdGuard = true;
    window.__trkOpenTaskModal = wrapped;
}
_wrapOpen();
setTimeout(_wrapOpen, 150);
setTimeout(_wrapOpen, 500);
setTimeout(_wrapOpen, 1500);
setTimeout(_wrapOpen, 3000);

// 2. Capture-перехват клика #saveTaskBtn — ДО обработчика saveTask
//    Если modal открыт как «Редактировать», но #task_id пуст — восстанавливаем.
document.addEventListener('click', function(e){
    if (!e.target || !e.target.closest) return;
    if (!e.target.closest('#saveTaskBtn')) return;

    var tm = document.getElementById('taskModal');
    if (!tm || !tm.classList.contains('active')) return;

    var el = _ensureHiddenInModal();
    if (!el) return;

    // Если #task_id уже корректно заполнен — ничего не делаем
    if (el.value) {
        _guardTaskId = el.value;   // синхронизируем
        return;
    }

    // #task_id пуст
    if (_guardTaskId) {
        // У нас есть id из последнего openTaskModal — используем
        el.value = _guardTaskId;
        return;
    }

    // #task_id пуст и в guard ничего нет — проверяем, не edit ли это
    if (!_isEditMode()) {
        // Новая задача — всё ок, id остаётся пустым
        return;
    }

    // Это edit, но id потерян — пытаемся восстановить по имени
    var nameInput = document.getElementById('task_name');
    var name = nameInput ? nameInput.value.trim() : '';
    var foundId = _findTaskIdByName(name);

    if (foundId) {
        el.value = foundId;
        _guardTaskId = foundId;
        console.warn('[task_id-guard] восстановлен id по имени:', foundId);
        return;
    }

    // Восстановить не удалось — ОТМЕНЯЕМ сохранение, чтобы не создать дубликат
    e.preventDefault();
    e.stopPropagation();
    if (e.stopImmediatePropagation) e.stopImmediatePropagation();
    _notify('❌ Не удалось определить редактируемую задачу. Переоткройте карточку.', 'error');
}, true);

// 3. Синхронизация при закрытии modal — сбрасываем guard
(function _watchClose(){
    var tm = document.getElementById('taskModal');
    if (!tm || tm._taskIdGuardClose) return;
    tm._taskIdGuardClose = true;
    new MutationObserver(function(){
        if (!tm.classList.contains('active')) {
            // Через 300ms после закрытия — если modal не переоткрылась, сбрасываем
            setTimeout(function(){
                if (!tm.classList.contains('active')) {
                    _guardTaskId = '';
                    _guardOpenTask = null;
                }
            }, 300);
        }
    }).observe(tm, { attributes: true, attributeFilter: ['class'] });
})();

// 4. Экспорт для отладки
window.__trkGetGuardTaskId = function(){ return _guardTaskId; };
window.__trkSetGuardTaskId = function(v){ _guardTaskId = String(v || ''); };

})();

