# PATCH 1.0.14/1.0.15: диалог при удалении исполнителей с отметками
_removed_assignees = set()
_removed_action = ''
if task_id:
    try:
        _old_a = {r.get('employee_id') for r in db.query(
            'SELECT employee_id FROM task_assignees WHERE task_id=?', (task_id,))}
    except Exception:
        _old_a = set()
    _new_a = set(assignees or [])
    _removed_assignees = {e for e in (_old_a - _new_a) if e}
    _removed_action = str(body.get('removed_logs_action') or '').strip().lower()
    if _removed_assignees:
        _pl = ','.join('?' * len(_removed_assignees))
        _logs = db.query(
            f'SELECT employee_id, COUNT(*) AS cnt, MIN(date) AS first_date, MAX(date) AS last_date '
            f'FROM work_logs WHERE task_id=? AND employee_id IN ({_pl}) '
            f'GROUP BY employee_id',
            (task_id, *list(_removed_assignees)),
        )
        if _logs and _removed_action not in ('delete', 'keep'):
            _info = []
            for _l in _logs:
                _emp = db.query_one('SELECT name FROM employees WHERE id=?', (_l['employee_id'],))
                _info.append({
                    'employee_id': _l['employee_id'],
                    'name': (_emp or {}).get('name', _l['employee_id']),
                    'logs_count': _l['cnt'],
                    'first_date': _l['first_date'],
                    'last_date': _l['last_date'],
                })
            return jsonify({
                'success': False,
                'error': 'removed_assignees_have_logs',
                'removed': _info,
                'task_id': task_id,
                'message': 'У удаляемых сотрудников есть отметки по этой задаче',
            }), 409

now_str = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
if not task_id:
