/* ============================================================
   PATCH 1.0.15 — 409 removed_assignees_have_logs: диалог выбора
   ============================================================ */
(function(){
'use strict';
if (window.__trkRemovedAssigneesFetchV1015) return;
window.__trkRemovedAssigneesFetchV1015 = true;

var _native = window.fetch;
if (typeof _native !== 'function') return;

function _esc(s){
    return String(s == null ? '' : s).replace(/[&<>"']/g, function(c){
        return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];
    });
}

function _showDialog(data){
    return new Promise(function(resolve){
        var ex = document.getElementById('trkRemovedAssigneesModal');
        if (ex) ex.remove();
        var m = document.createElement('div');
        m.id = 'trkRemovedAssigneesModal';
        m.className = 'modal trk-removed-assignees-modal';
        m.style.setProperty('z-index', '9000', 'important');

        var rows = (data.removed || []).map(function(r){
            var per = '';
            if (r.first_date && r.last_date) {
                per = r.first_date === r.last_date ? r.first_date : (r.first_date + ' — ' + r.last_date);
            }
            return '<div class="trk-ra-row">'
                + '<span class="trk-ra-name">' + _esc(r.name) + '</span>'
                + '<span class="trk-ra-meta">' + (r.logs_count || 0) + ' отм. · ' + _esc(per) + '</span>'
                + '</div>';
        }).join('');

        m.innerHTML = ''
            + '<div class="modal-content">'
            + '  <h2>⚠ Удаление сотрудников из задачи</h2>'
            + '  <p class="trk-ra-sub">Следующие сотрудники будут удалены из задачи, но у них есть отметки:</p>'
            + '  <div class="trk-ra-list">' + rows + '</div>'
            + '  <p class="trk-ra-q">Что сделать с их отметками?</p>'
            + '  <div class="modal-actions trk-ra-actions">'
            + '    <button type="button" class="btn btn-danger" data-ra="delete">🗑 Удалить отметки</button>'
            + '    <button type="button" class="btn btn-secondary" data-ra="keep">💾 Оставить отметки</button>'
            + '    <button type="button" class="btn btn-secondary" data-ra="cancel">Отмена</button>'
            + '  </div>'
            + '</div>';
        document.body.appendChild(m);
        m.classList.add('active');

        var done = false;
        function finish(choice){
            if (done) return; done = true;
            m.classList.remove('active');
            m.removeEventListener('click', onClick);
            resolve(choice);
        }
        function onClick(e){
            if (e.target === m) return;
            var btn = e.target.closest && e.target.closest('[data-ra]');
            if (!btn) return;
            finish(btn.getAttribute('data-ra'));
        }
        m.addEventListener('click', onClick);
    });
}

window.fetch = function(url, opts){
    var isSave = (typeof url === 'string' && url.indexOf('/api/tracker/task/save') !== -1);
    var isPost = opts && (opts.method || 'GET').toUpperCase() === 'POST';
    if (!isSave || !isPost) return _native.apply(this, arguments);
    var body = {};
    try { body = JSON.parse(opts.body || '{}'); } catch(e){}
    if (body.removed_logs_action) return _native.apply(this, arguments);
    var self = this;
    return _native.apply(this, arguments).then(function(r){
        if (r.status !== 409) return r;
        return r.clone().json().then(function(d){
            if (!d || d.error !== 'removed_assignees_have_logs') return r;
            return _showDialog(d).then(function(choice){
                if (choice === 'cancel') {
                    return new Response(JSON.stringify({success: false, error: 'cancelled'}), {
                        status: 200, headers: {'Content-Type': 'application/json'}
                    });
                }
                var nb = Object.assign({}, body, {removed_logs_action: choice});
                var no = Object.assign({}, opts, {body: JSON.stringify(nb)});
                return _native.call(self, url, no);
            });
        });
    });
};

})();

/* ============================================================
   PATCH 1.0.15 — диалог «Удаляемые исполнители с отметками»
   ============================================================ */
.trk-removed-assignees-modal .modal-content {
    max-width: 560px;
    border: 1px solid rgba(241, 196, 15, 0.45);
}
.trk-removed-assignees-modal h2 {
    color: #f1c40f !important;
    background: none !important;
    -webkit-text-fill-color: #f1c40f !important;
    border-bottom: 1px solid rgba(241, 196, 15, 0.18) !important;
    padding-bottom: 10px !important;
}
body.trk-theme-light .trk-removed-assignees-modal h2 {
    color: #b7791f !important;
    -webkit-text-fill-color: #b7791f !important;
}
.trk-ra-sub { color: var(--trk-meta); font-size: 0.85rem; margin-bottom: 10px; line-height: 1.4; }
.trk-ra-list {
    background: var(--trk-hover-row);
    border: 1px solid var(--trk-card-border);
    border-radius: 10px;
    padding: 10px 14px;
    margin-bottom: 14px;
    max-height: 260px;
    overflow-y: auto;
}
.trk-ra-row {
    display: flex; justify-content: space-between; align-items: baseline;
    gap: 12px; padding: 7px 0;
    border-bottom: 1px dashed var(--trk-border-soft);
    font-size: 0.88rem;
}
.trk-ra-row:last-child { border-bottom: none; }
.trk-ra-name { font-weight: 700; color: var(--trk-text); word-break: break-word; }
.trk-ra-meta { color: var(--trk-meta); font-size: 0.75rem; white-space: nowrap; font-family: monospace; }
.trk-ra-q { font-weight: 700; color: var(--trk-text); margin-bottom: 8px; font-size: 0.9rem; }
.trk-ra-actions { gap: 8px; }
body.trk-theme-light .trk-ra-list { background: #ffffff; border-color: rgba(0,0,0,0.14); }
